// client/src/components/ExerciseCard.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { ethers } from 'ethers'; // Import ethers

const ExerciseCard = ({ exercise, currentAccount }) => {
  const [selected, setSelected] = useState(null);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [statusMsg, setStatusMsg] = useState(""); // Thêm dòng trạng thái

  const handleSubmit = async () => {
    if (selected === null) return alert("Vui lòng chọn đáp án!");
    if (!currentAccount) return alert("Kết nối ví để tiếp tục!");

    setLoading(true);
    setStatusMsg("🚀 Đang khởi tạo giao dịch Blockchain...");

    try {
      // --- BƯỚC 1: GỌI METAMASK ĐỂ CHUYỂN TIỀN CƯỢC (STAKE) ---
      // Yêu cầu người dùng chuyển 'stake_amount' (VD: 0.0001 ETH) cho Creator
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      
      // Chuyển đổi số token cược sang đơn vị Wei (Ở đây ví dụ cược 0.0001 ETH)
      // Trong thực tế bạn có thể lấy exercise.stake_amount nếu muốn
      const stakeValue = ethers.parseEther("0.0001"); 

      setStatusMsg("⏳ Vui lòng xác nhận trên MetaMask...");
      
      // Thực hiện giao dịch chuyển tiền trực tiếp (P2P)
      const tx = await signer.sendTransaction({
        to: exercise.creator_address,
        value: stakeValue
      });

      setStatusMsg("⛓️ Đang chờ xác nhận trên Blockchain...");
      await tx.wait(); // Chờ giao dịch hoàn tất

      // --- BƯỚC 2: GỬI KẾT QUẢ VỀ SERVER CHẤM ĐIỂM ---
      setStatusMsg("📤 Đang gửi bài làm...");
      
      const res = await axios.post('http://localhost:5000/api/submit-answer', {
        exercise_id: exercise._id,
        learner_address: currentAccount,
        selected_option_index: selected,
        stake_tx_hash: tx.hash // Gửi kèm bằng chứng đã nộp tiền cược
      });

      setResult(res.data);
      setStatusMsg(""); 

    } catch (err) {
      console.error(err);
      // Xử lý lỗi người dùng từ chối giao dịch
      if (err.code === 'ACTION_REJECTED') {
        setStatusMsg("❌ Bạn đã từ chối giao dịch.");
      } else {
        setStatusMsg("❌ Lỗi: " + (err.response?.data?.error || err.message));
      }
    }
    setLoading(false);
  };

  // ... (Phần return giao diện giữ nguyên như cũ, chỉ thêm hiển thị statusMsg) ...
  
  return (
    <div className="glass-panel p-6 flex flex-col h-full relative group">
      {/* ... (Code cũ giữ nguyên) ... */}

      {/* Hiển thị trạng thái Loading chi tiết */}
      {loading && (
        <div className="absolute inset-0 bg-black/80 z-20 rounded-2xl flex flex-col items-center justify-center text-center p-4">
          <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-3"></div>
          <p className="text-indigo-300 font-bold animate-pulse">{statusMsg}</p>
        </div>
      )}

      {/* ... (Phần hiển thị options và footer cũ) ... */}
       {/* Footer */}
        {result ? (
          <div className={`p-4 rounded-xl text-center border animate-fade-in ${
            result.is_correct ? 'bg-emerald-500/10 border-emerald-500/30' : 'bg-red-500/10 border-red-500/30'
          }`}>
            <p className={`font-bold ${result.is_correct ? 'text-emerald-400' : 'text-red-400'}`}>
              {result.message}
            </p>
            
            {/* Hiển thị Hash trả thưởng nếu đúng */}
            {result.reward_tx_hash && (
              <a 
                href={`https://sepolia.etherscan.io/tx/${result.reward_tx_hash}`} 
                target="_blank" 
                rel="noreferrer"
                className="text-xs text-emerald-400 underline mt-2 block hover:text-emerald-300"
              >
                Xem thưởng trên Etherscan ↗
              </a>
            )}
             {/* Hiển thị Hash cược */}
             <a 
                href={`https://sepolia.etherscan.io/tx/${result.stake_tx_hash}`} 
                target="_blank" 
                rel="noreferrer"
                className="text-xs text-gray-500 underline mt-1 block hover:text-gray-400"
              >
                Xem tiền cược đã chuyển ↗
              </a>
          </div>
        ) : (
          <button 
            onClick={handleSubmit}
            disabled={loading || selected === null}
            className={`w-full py-3 rounded-xl font-bold transition-all ${
              loading 
                ? 'bg-gray-700 text-gray-400 cursor-wait'
                : selected !== null 
                  ? 'btn-primary' 
                  : 'bg-gray-800 text-gray-500 cursor-not-allowed'
            }`}
          >
            {loading ? 'Đang xử lý...' : `Cược 0.0001 ETH & Nộp bài`}
          </button>
        )}
    </div>
  );
};

export default ExerciseCard;
